/* --- Navbar scroll --- */
const navbar = document.getElementById('navbar');
window.addEventListener('scroll', () => {
  navbar.classList.toggle('scrolled', window.scrollY > 30);
});

/* --- Tabs --- */
function setTab(el) {
  document.querySelectorAll('.form-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
}

/* --- Booking button --- */
function handleBook() {
  const btn = document.querySelector('.btn-book');
  btn.textContent = '⏳ Vérification...';
  btn.style.opacity = '0.7';
  setTimeout(() => {
    btn.textContent = '✓ Disponible ! Confirmez la réservation →';
    btn.style.opacity = '1';
    btn.style.background = 'linear-gradient(135deg, #3a7a4a, #5aaa6a)';
  }, 1500);
}

/* --- Filtrage des bagages --- */
const filterButtons = document.querySelectorAll('.filter-pills .pill');
const catalogueProducts = document.querySelectorAll('#catalog .products-grid > .product-card');

filterButtons.forEach(button => {
  button.addEventListener('click', function() {
    const selectedFilter = this.dataset.filter;

    // Mettre à jour le bouton sélectionné.
    filterButtons.forEach(pill => {
      pill.classList.remove('active');
      pill.setAttribute('aria-pressed', 'false');
    });
    this.classList.add('active');
    this.setAttribute('aria-pressed', 'true');

    // Afficher uniquement les bagages correspondant à la catégorie.
    catalogueProducts.forEach(product => {
      const categories = (product.dataset.category || '').split(' ');
      const shouldDisplay = selectedFilter === 'tout' || categories.includes(selectedFilter);

      product.classList.toggle('is-filtered-out', !shouldDisplay);
    });
  });
});

/* --- Intersection Observer (reveal) --- */
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.12 });

document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

/* --- Counter animation --- */
function animateCounter(el, target, duration = 2000) {
  let start = 0;
  const step = (timestamp) => {
    if (!start) start = timestamp;
    const progress = Math.min((timestamp - start) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    el.textContent = Math.floor(eased * target).toLocaleString('fr-FR') + '+';
    if (progress < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

const counterEl = document.getElementById('counter-clients');
const counterObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateCounter(counterEl, 15000);
      counterObserver.disconnect();
    }
  });
}, { threshold: 0.5 });
counterObserver.observe(counterEl);

/* --- Smooth scroll for nav links --- */
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function(e) {
    e.preventDefault();
    const target = document.querySelector(this.getAttribute('href'));
    if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
  });
});

/* --- FAQ toggle icon --- */
document.querySelectorAll('details').forEach(detail => {
  const summary = detail.querySelector('summary');
  const icon = summary.querySelector('span');
  detail.addEventListener('toggle', () => {
    icon.textContent = detail.open ? '−' : '+';
  });
});

/* ============================================================
   TOGGLE THÈME LIGHT / DARK
   ============================================================ */
function toggleTheme() {
  const body = document.body;
  const btn  = document.getElementById('themeToggle');
  body.classList.toggle('dark-mode');
  const isDark = body.classList.contains('dark-mode');
  btn.textContent = isDark ? '☀️' : '🌙';
  btn.title = isDark ? 'Passer en mode clair' : 'Passer en mode sombre';
  localStorage.setItem('bagaway-theme', isDark ? 'dark' : 'light');
}

/* Restaurer le thème sauvegardé */
(function() {
  if (localStorage.getItem('bagaway-theme') === 'dark') {
    document.body.classList.add('dark-mode');
    const btn = document.getElementById('themeToggle');
    if (btn) { btn.textContent = '☀️'; btn.title = 'Passer en mode clair'; }
  }
})();

