let currentDuration = 3;
let currentProductKey = 'cabin';

function openProduct(key) {
  const product = PRODUCTS[key] || PRODUCTS.cabin;
  currentProductKey = key;

  /* Mettre à jour le contenu */
  document.getElementById('pp-breadcrumb-name').textContent = product.name;
  document.getElementById('pp-name').textContent = product.name;
  const imgSrc = IMG[key];
  const mainEl = document.getElementById('pp-main-emoji');
  if (imgSrc) {
    mainEl.innerHTML = '<img src="' + imgSrc + '" alt="' + product.name + '" style="width:100%;height:100%;object-fit:contain;padding:24px;border-radius:var(--r-lg);">';
    mainEl.style.background = 'var(--surface)';
  } else {
    mainEl.innerHTML = product.emoji + '<div style="position:absolute;inset:0;background:radial-gradient(ellipse at 30% 30%,rgba(201,168,76,0.08),transparent 60%);"></div>';
  }
  document.getElementById('pp-badge').textContent = product.badge;
  document.getElementById('pp-price').textContent = product.price + '€';
  document.getElementById('pp-spec-capacity').textContent = product.capacity;
  document.getElementById('pp-spec-weight').textContent = product.weight;
  document.getElementById('pp-spec-dims').textContent = product.dims;
  document.getElementById('pp-spec-material').textContent = product.material;
  document.getElementById('pp-spec-lock').textContent = product.lock;
  document.getElementById('pp-desc').innerHTML = product.desc + ' <br><br>Chaque bagage BagAway est soumis à un protocole de nettoyage rigoureux en 5 étapes avant chaque location. Vous recevez un <strong style="color:var(--text)">certificat de propreté</strong> avec votre commande.';

  /* Thumbnails selon le produit */
  const imgSrcThumb = IMG[key];
  const thumbViews = imgSrcThumb
    ? [
        { src: imgSrcThumb, label: 'Vue principale' },
        { src: imgSrcThumb, label: 'Vue côté' },
        { src: imgSrcThumb, label: 'Détail' },
        { src: imgSrcThumb, label: 'Fermeture' }
      ]
    : [{ emoji: product.emoji }, { emoji: '🔒' }, { emoji: '✈️' }, { emoji: '🏷️' }];

  document.querySelectorAll('.pp-thumb').forEach((thumb, i) => {
    const view = thumbViews[i] || thumbViews[0];
    if (view.src) {
      thumb.innerHTML = '<img src="' + view.src + '" alt="' + (view.label||'') + '" style="width:100%;height:100%;object-fit:contain;padding:6px;">';
      thumb.dataset.imgSrc = view.src;
      thumb.dataset.emoji = '';
    } else {
      thumb.textContent = view.emoji || '📦';
      thumb.dataset.emoji = view.emoji || '📦';
      thumb.dataset.imgSrc = '';
    }
    thumb.classList.toggle('active', i === 0);
  });

  /* Reset durée & dates */
  currentDuration = 3;
  document.querySelectorAll('.pp-dur-btn').forEach((btn, i) => btn.classList.toggle('active', i === 1));
  
  const today = new Date();
  const end   = new Date(today); end.setDate(end.getDate() + 3);
  document.getElementById('pp-date-start').value = today.toISOString().split('T')[0];
  document.getElementById('pp-date-end').value   = end.toISOString().split('T')[0];
  updateTotal();

  /* Afficher la page produit */
  document.getElementById('main-page').classList.add('hidden');
  document.getElementById('product-page').classList.add('active');
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

