function selectPaymentMethod(method) {
  currentPaymentMethod = method;
  document.querySelectorAll('.pay-method').forEach(btn => {
    btn.classList.toggle('active', btn.id === 'method-' + method);
  });
  ['card', 'paypal', 'applepay', 'gpay', 'transfer'].forEach(m => {
    const panel = document.getElementById('panel-' + m);
    if (panel) panel.style.display = m === method ? 'block' : 'none';
  });
}

function formatCardNumber(el) {
  let digits = el.value.replace(/\D/g, '').slice(0, 16);
  el.value = digits.replace(/(.{4})/g, '$1 ').trim();

  const brandEl = document.getElementById('pay-card-brand');
  if (digits.startsWith('4')) brandEl.textContent = '💳 Visa';
  else if (/^5[1-5]/.test(digits)) brandEl.textContent = '💳 Mastercard';
  else if (digits.startsWith('3')) brandEl.textContent = '💳 Amex';
  else brandEl.textContent = '💳';
}

function formatExpiry(el) {
  let digits = el.value.replace(/\D/g, '').slice(0, 4);
  if (digits.length >= 3) {
    el.value = digits.slice(0, 2) + '/' + digits.slice(2);
  } else {
    el.value = digits;
  }
}

function processPayment() {
  if (!document.getElementById('pay-cgv').checked) {
    showToast('error', '⚠️', 'Veuillez accepter les Conditions Générales de Vente.');
    return;
  }
  if (!document.getElementById('pay-firstname').value.trim() ||
      !document.getElementById('pay-lastname').value.trim() ||
      !document.getElementById('pay-email').value.trim() ||
      !document.getElementById('pay-address').value.trim()) {
    showToast('error', '⚠️', 'Veuillez compléter vos coordonnées.');
    return;
  }
  if (!emailVerified || document.getElementById('pay-email').value.trim() !== verifiedEmail) {
    showToast('error', '⚠️', 'Veuillez vérifier votre adresse e-mail avant de continuer.');
    return;
  }

  if (currentPaymentMethod === 'card') {
    const number = document.getElementById('pay-card-number').value.replace(/\s/g, '');
    const expiry = document.getElementById('pay-card-expiry').value;
    const cvc = document.getElementById('pay-card-cvc').value;
    const name = document.getElementById('pay-card-name').value.trim();
    if (number.length < 16 || !/^\d{2}\/\d{2}$/.test(expiry) || cvc.length < 3 || !name) {
      showToast('error', '⚠️', 'Veuillez vérifier les informations de votre carte.');
      return;
    }
  }

  const btn = document.getElementById('pay-submit-btn');
  const originalHTML = btn.innerHTML;
  btn.disabled = true;
  btn.innerHTML = '<span class="btn-spinner"></span>Traitement du paiement…';

  setTimeout(() => {
    btn.disabled = false;
    btn.innerHTML = originalHTML;

    const orderNum = '#BA-' + Math.floor(100000 + Math.random() * 900000);
    document.getElementById('confirm-email').textContent = document.getElementById('pay-email').value.trim();
    document.getElementById('confirm-order-num').textContent = orderNum;

    document.getElementById('payment-form-view').style.display = 'none';
    document.getElementById('payment-confirm').classList.add('active');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, 1800);
}


const FORMSPREE_URL = 'https://formspree.io/f/mvzvrgyv';
let currentTab = 'login';

function openModal() {
  document.getElementById('modalOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
  setTimeout(() => document.getElementById('inputEmail').focus(), 350);
}

function closeModal() {
  document.getElementById('modalOverlay').classList.remove('open');
  document.body.style.overflow = '';
  resetForm();
}

/* Fermer avec Échap */
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModal();
});

/* Basculer entre Connexion et Inscription */
function switchTab(tab) {
  currentTab = tab;
  const isRegister = tab === 'register';

  document.getElementById('tabLogin').classList.toggle('active', !isRegister);
  document.getElementById('tabRegister').classList.toggle('active', isRegister);

  /* Champs spécifiques à l'inscription */
  document.querySelectorAll('.field-register').forEach(el => {
    el.style.display = isRegister ? 'block' : 'none';
  });

  /* Options (se souvenir / oublié) */
  document.getElementById('loginOptions').style.display = isRegister ? 'none' : 'flex';

  /* Autocomplete mot de passe */
  document.getElementById('inputPassword').setAttribute(
    'autocomplete', isRegister ? 'new-password' : 'current-password'
  );

  /* Textes dynamiques */
  document.getElementById('modalTitle').innerHTML = isRegister
    ? 'Rejoignez<br>BagAway <em>✦</em>'
    : 'Bon retour<br>parmi nous <em>✦</em>';
  document.getElementById('modalSubtitle').textContent = isRegister
    ? 'Créez votre compte gratuit en quelques secondes.'
    : 'Connectez-vous pour accéder à vos réservations.';
  document.getElementById('modalSubmit').textContent = isRegister
    ? 'Créer mon compte'
    : 'Se connecter';
  document.getElementById('hiddenAction').value = isRegister ? 'inscription' : 'connexion';
  document.getElementById('hiddenSubject').value = isRegister
    ? '🎉 Nouvelle inscription BagAway'
    : '🔑 Nouvelle connexion BagAway';
  document.getElementById('modalFooterTxt').innerHTML = isRegister
    ? 'Déjà un compte ? <a href="#" onclick="switchTab(\'login\'); return false;">Se connecter</a>'
    : 'Pas encore de compte ? <a href="#" onclick="switchTab(\'register\'); return false;">Créer un compte gratuit</a>';

  resetForm();
}

/* Afficher / masquer le mot de passe */
function togglePw() {
  const input = document.getElementById('inputPassword');
  const btn   = document.getElementById('pwToggle');
  const isHidden = input.type === 'password';
  input.type = isHidden ? 'text' : 'password';
  btn.textContent = isHidden ? '🙈' : '👁️';
}

/* Validation côté client */
function validateForm() {
  const email    = document.getElementById('inputEmail').value.trim();
  const password = document.getElementById('inputPassword').value;

  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    showToast('error', '⚠️', 'Veuillez saisir un e-mail valide.');
    return false;
  }
  if (password.length < 6) {
    showToast('error', '⚠️', 'Le mot de passe doit contenir au moins 6 caractères.');
    return false;
  }
  if (currentTab === 'register') {
    const name    = document.getElementById('inputName').value.trim();
    const confirm = document.getElementById('inputConfirm').value;
    if (!name) {
      showToast('error', '⚠️', 'Veuillez saisir votre nom.');
      return false;
    }
    if (password !== confirm) {
      showToast('error', '⚠️', 'Les mots de passe ne correspondent pas.');
      return false;
    }
  }
  return true;
}

/* Envoi vers Formspree */
document.getElementById('modalForm').addEventListener('submit', async function(e) {
  e.preventDefault();
  if (!validateForm()) return;

  const btn = document.getElementById('modalSubmit');
  const originalText = btn.textContent;

  /* État chargement */
  btn.disabled = true;
  btn.innerHTML = '<span class="btn-spinner"></span>Envoi en cours…';

  const formData = new FormData(this);

  try {
    const res = await fetch(FORMSPREE_URL, {
      method: 'POST',
      body: formData,
      headers: { 'Accept': 'application/json' }
    });

    if (res.ok) {
      showToast('success', '✅', currentTab === 'register'
        ? 'Compte créé avec succès ! Bienvenue chez BagAway.'
        : 'Connexion réussie ! Bon voyage 🧳');
      setTimeout(closeModal, 2000);
    } else {
      const data = await res.json();
      const msg = data?.errors?.[0]?.message || 'Une erreur est survenue.';
      showToast('error', '❌', msg);
    }
  } catch (err) {
    showToast('error', '❌', 'Impossible de contacter le serveur. Vérifiez votre connexion.');
  } finally {
    btn.disabled = false;
    btn.textContent = originalText;
  }
});

/* Toast */
let toastTimer;
function showToast(type, icon, msg) {
  const toast   = document.getElementById('modalToast');
  const iconEl  = document.getElementById('toastIcon');
  const msgEl   = document.getElementById('toastMsg');

  toast.className = 'modal-toast ' + type;
  iconEl.textContent = icon;
  msgEl.textContent  = msg;

  toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('show'), 4000);
}

/* Réinitialiser */
function resetForm() {
  document.getElementById('modalForm').reset();
  document.getElementById('modalSubmit').disabled = false;
}

/* OAuth placeholder */
function oauthNotice() {
  showToast('error', 'ℹ️', 'Connexion sociale bientôt disponible !');
}

/* Copier le code promo de la bannière */
function copyPromoCode() {
  const code = 'BAGAWAY10';
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(code)
      .then(() => showToast('success', '✓', 'Code ' + code + ' copié ! À saisir lors du paiement.'))
      .catch(() => showToast('success', '🎁', 'Votre code : ' + code + ' (à saisir au paiement).'));
  } else {
    showToast('success', '🎁', 'Votre code : ' + code + ' (à saisir au paiement).');
  }
}

